from pathlib import Path
import json,re
R=Path('/workspace/work/deliverables/diecut');C=R/'collection/diecut';REF=Path('/workspace/work/reference')
roots={p.name:json.load(open(REF/'samples/annual/elements'/p.name/'element.json')) for p in (C/'elements').iterdir()}
tax=json.load(open(REF/'contract/taxonomy.json'));byid={c['id']:c for c in tax['contracts']}
css={}
def add(n,s):css[n]=css.get(n,'')+s+'\n'
def root(n):return ':is('+','.join('.'+r+'[data-el="diecut-'+n+'"]'for r in byid[roots[n]['contract']]['roots'])+')'
# Common typographic parts are emitted separately under every contract root, never globally.
for n in roots:
 r=root(n)
 add(n,f'''{r}{{position:relative;min-width:0;min-height:0;max-width:100%;box-sizing:border-box;container-type:size;anchor-scope:all;color:var(--ink);font-family:var(--font-body);font-size:var(--type-20);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track)}}
{r} *,{r} *:before,{r} *:after{{box-sizing:border-box}}
{r} :is(p,h2,blockquote){{margin:0}}
{r} .name{{font-family:var(--font-display);font-size:var(--type-24);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track);overflow-wrap:anywhere}}
{r} .note{{font-size:var(--type-18);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-8);overflow-wrap:anywhere}}
{r} .kick{{font-size:var(--type-14);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);color:var(--n-7)}}
{r} .fig{{font-family:var(--font-display);font-size:var(--type-56);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track);font-variant-numeric:tabular-nums}}
{r} small{{font-size:var(--type-20);font-weight:var(--body-weight)}}
{r} .icon{{display:inline-block;width:32px;height:32px;flex:none}}
@container(max-width:600px){{{r} .name{{font-size:var(--type-20)}}{r} .note{{font-size:var(--type-16)}}{r} .fig{{font-size:var(--type-40)}}}}
@container(max-width:350px){{{r} .name{{font-size:var(--type-18)}}{r} .note{{font-size:var(--type-14)}}{r} .fig{{font-size:var(--type-32)}}{r} .kick{{display:none}}}}
@container(max-height:160px){{{r} .note{{display:none}}{r} .fig{{font-size:var(--type-28)}}{r} .name{{font-size:var(--type-18)}}}}
''')
# Surface and content
add('card','''R{background:var(--n-1);border-radius:var(--radius);padding:var(--pad);display:flex;align-items:stretch;border:var(--stroke) solid var(--n-2)}R .parts{display:flex;flex:1;min-width:0;flex-direction:column;justify-content:center;gap:var(--gap);text-align:center}R .parts>.name{min-height:2.5em;display:flex;align-items:center;justify-content:center}R .parts>.note{min-height:4.5em}R .mark{display:flex;align-items:center;justify-content:center;align-self:center;width:72px;height:72px;border-radius:999px;background:var(--a1-2-soft);font-size:var(--type-28);font-weight:var(--label-weight)}R .mark .icon{width:40px;height:40px}R.on{background:var(--a1);border-color:var(--a1);color:var(--a1-on)}R.on :is(.note,.kick){color:var(--a1-on)}R.quiet{background:var(--page);border-color:var(--page)}R.line{background:var(--page);border-color:var(--n-5)}R:is(.tone-2,.tone-3,.tone-4,.tone-5){background:var(--n-2)}R.tone-1{background:var(--a1-2-soft)}@container(max-width:350px){R .parts{gap:var(--gap-sm)}R .parts>.note{min-height:0}R .mark{width:56px;height:56px}R .mark .icon{width:30px;height:30px}}''')
add('pill','''R{display:flex;align-items:center;justify-content:center}R .parts{width:100%;display:flex;align-items:center;justify-content:center;gap:var(--gap);padding:var(--gap-sm) var(--pad);background:var(--n-2);border-radius:999px;min-height:48px}R .name{font-size:var(--type-20)}R .note{font-size:var(--type-16)}R.on .parts{background:var(--a1);color:var(--a1-on)}R.on .note{color:var(--a1-on)}R.line .parts{border:var(--stroke) solid var(--n-5);background:var(--page)}R.quiet .parts{background:var(--n-1)}R .mark{display:flex;align-items:center;justify-content:center;font-size:var(--type-18)}@container(max-width:450px){R .parts{gap:var(--gap-sm);padding:var(--gap-sm) var(--gap)}R .name{font-size:var(--type-16)}R .note{display:none}}''')
add('tag','''R.tag{display:inline-flex;align-items:center;justify-content:center;vertical-align:middle;min-height:32px;padding:var(--gap-sm) var(--gap);background:var(--a1);color:var(--a1-on);border-radius:999px;font-size:var(--type-16);font-weight:var(--label-weight);line-height:var(--label-line)}R.hl{display:inline;background:linear-gradient(0deg,var(--a1-2-soft) 50%,transparent 50%);font-size:inherit;font-weight:var(--name-weight);padding:0 var(--gap-sm)}''')
add('callout','''R{display:flex;align-items:center;justify-content:center;gap:var(--gap);padding:var(--pad);background:var(--n-9);color:var(--page);border-radius:999px}R p{font-size:var(--type-28);font-weight:var(--body-weight);line-height:var(--lead-line);letter-spacing:var(--lead-track);text-align:center}R p b{font-weight:var(--name-weight);color:var(--page);text-decoration:underline;text-underline-offset:.25em;text-decoration-color:var(--a1)}R .icon{color:var(--a1);width:40px;height:40px}@container(max-width:650px){R p{font-size:var(--type-20)}}@container(max-height:140px){R p{font-size:var(--type-18)}R .icon{width:28px;height:28px}}''')
add('headline','''R{display:flex;flex-direction:column;justify-content:center;gap:var(--gap);padding:var(--gap);text-align:left}R h2{font-family:var(--font-display);font-size:var(--type-44);font-weight:var(--title-weight);line-height:var(--title-line);letter-spacing:var(--title-track);word-break:keep-all}R h2 b{font-weight:var(--title-weight);background:linear-gradient(0deg,var(--a1-2-soft) 45%,transparent 45%)}R.big h2{font-size:var(--type-64)}R.center{text-align:center;align-items:center}R.on{padding:var(--pad);border-radius:var(--radius);background:var(--a1);color:var(--a1-on)}R.on :is(.kick,.note){color:var(--a1-on)}@container(max-width:600px){R h2{font-size:var(--type-32)}R.big h2{font-size:var(--type-44)}}@container(max-width:350px){R h2,R.big h2{font-size:var(--type-28)}}''')
add('prose','''R{display:flex;flex-direction:column;justify-content:center;gap:var(--gap);padding:var(--gap);font-size:var(--type-22)}R p{line-height:var(--body-line);letter-spacing:var(--body-track)}R p b{font-weight:var(--name-weight)}R.lead{font-size:var(--type-28)}R.quiet{color:var(--n-7)}R.cols{display:block;column-count:2;column-gap:var(--gap-lg)}R.cols p{margin-bottom:var(--gap)}@container(max-width:600px){R,R.lead{font-size:var(--type-18)}R.cols{column-count:1}}@container(max-height:160px){R,R.lead{font-size:var(--type-16)}}''')
add('list','''R{display:flex;flex-direction:column;justify-content:center;gap:var(--gap);counter-reset:item;padding:var(--gap)}R>.item{position:relative;padding-left:var(--gap-lg);counter-increment:item;display:flex;flex-direction:column;gap:var(--gap-sm)}R>.item:before{content:'';position:absolute;left:0;top:.55em;width:6px;height:6px;border-radius:999px;background:var(--ink)}R.num>.item:before{content:counter(item,decimal-leading-zero);top:0;width:24px;height:24px;background:var(--a1);color:var(--a1-on);display:flex;align-items:center;justify-content:center;font-size:var(--type-14);font-weight:var(--label-weight)}R.check>.item:before{width:7px;height:12px;top:.2em;border-radius:0;background:none;border-right:2px solid var(--ink);border-bottom:2px solid var(--ink);transform:rotate(45deg)}R.divided>.item{padding-bottom:var(--gap);border-bottom:var(--stroke) solid var(--n-3)}R .mark{position:absolute;left:0;top:0}R .mark .icon{width:20px;height:20px}R .name{font-size:var(--type-22)}@container(max-height:300px){R{gap:var(--gap-sm)}R .name{font-size:var(--type-18)}R .note{font-size:var(--type-14)}}''')
add('quote','''R{display:flex;flex-direction:column;justify-content:center;gap:var(--gap-lg);background:var(--n-1);border-radius:var(--radius);padding:var(--pad)}R blockquote{font-size:var(--type-32);font-weight:var(--body-weight);line-height:var(--lead-line);letter-spacing:var(--lead-track);text-align:center}R.big blockquote{font-size:var(--type-44)}R .by{display:grid;grid-template-columns:64px 1fr;gap:var(--gap-sm) var(--gap);align-self:center;align-items:center}R .by .seat{grid-row:span 2;width:64px;height:64px}R .by .name{align-self:end}R .by .note{align-self:start}@container(max-width:650px){R blockquote,R.big blockquote{font-size:var(--type-24)}}''')
add('metric','''R.stats{display:flex;align-items:center;justify-content:center;gap:var(--gap)}R.stat{display:flex;justify-content:center;align-items:center;padding:var(--pad)}R.stats>.stat{flex:1;border-left:var(--stroke) solid var(--n-4)}R.stats>.stat:first-child{border-left:0}R .parts{display:flex;flex-direction:column;align-items:center;text-align:center;gap:var(--gap)}R .fig{font-size:var(--type-64)}R .name{font-size:var(--type-24)}@container(max-width:450px){R .parts{gap:var(--gap-sm)}R .fig{font-size:var(--type-36)}R .name{font-size:var(--type-18)}}''')
