# bars use flexible plot lanes and room above each value
add('chart-bar','''R{display:flex;gap:var(--gap);align-items:stretch;padding:var(--gap-lg) var(--gap) var(--gap-lg);border-bottom:var(--stroke) solid var(--n-4)}R>.bar{position:relative;flex:1;min-width:0;display:flex;flex-direction:column;justify-content:flex-end;align-items:center}R>.bar:before{content:'';position:absolute;bottom:0;left:12%;right:12%;height:calc(var(--v)/var(--max)*88%);background:var(--n-9)}R>.bar.on:before{background:var(--a1)}R>.bar.tone-2:before{background:var(--n-6)}R>.bar.tone-3:before{background:var(--n-4)}R>.bar b{position:absolute;bottom:calc(var(--v)/var(--max)*88% + var(--gap-sm));font-size:var(--type-22);font-weight:var(--figure-weight);line-height:var(--figure-line);white-space:nowrap}R>.bar>span{position:absolute;top:calc(100% + var(--gap-sm));font-size:var(--type-16);line-height:var(--label-line);white-space:nowrap}R.h{flex-direction:column;padding:var(--gap) var(--gap-lg);border-bottom:0}R.h>.bar{align-items:flex-start;justify-content:center;padding-left:var(--pad)}R.h>.bar:before{height:64%;top:18%;bottom:auto;left:22%;right:auto;width:calc(var(--v)/var(--max)*65%)}R.h>.bar b{left:calc(22% + var(--v)/var(--max)*65% + var(--gap-sm));bottom:auto;font-size:var(--type-20)}R.h>.bar>span{left:0;top:auto;font-size:var(--type-18)}@container(max-width:700px){R{gap:var(--gap-sm)}R>.bar b{font-size:var(--type-18)}R>.bar>span{font-size:var(--type-14)}}@container(max-width:500px){R:not(.h)>.bar:nth-child(even)>span{visibility:hidden}R.h>.bar b{font-size:var(--type-16)}R.h>.bar>span{font-size:var(--type-14)}}''')
# Line segments are bounded rectangles between point anchors, with one diagonal selected by valid geometry.
add('chart-line','''R{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;padding:var(--gap-lg) var(--gap);isolation:isolate}R>.pt{display:contents}R>.pt>b{grid-row:1;align-self:start;height:calc(100% - var(--v)/var(--max)*(100% - 36px));display:flex;flex-direction:column;align-items:center;justify-content:flex-end;font-size:var(--type-22);font-weight:var(--figure-weight);line-height:var(--figure-line);white-space:nowrap;anchor-name:var(--diecut-self)}R>.pt>b:after{content:'';display:block;width:8px;height:8px;border-radius:999px;background:var(--ink);margin-top:var(--gap-sm);z-index:2}R>.pt.on>b:after{background:var(--a1)}R>.pt>span{grid-row:2;font-size:var(--type-16);text-align:center;border-top:var(--stroke) solid var(--n-4);padding-top:var(--gap)}R>.pt:before,R>.pt:after{content:'';position:absolute;left:anchor(var(--diecut-prev) center);right:anchor(var(--diecut-self) center);z-index:-1}R>.pt:before{top:calc(anchor(var(--diecut-prev) bottom) - 4px);bottom:calc(anchor(var(--diecut-self) bottom) - 4px);background:linear-gradient(to top right,transparent calc(50% - 1px),var(--ink) calc(50% - .5px),var(--ink) calc(50% + .5px),transparent calc(50% + 1px))}R>.pt:after{top:calc(anchor(var(--diecut-self) bottom) - 4px);bottom:calc(anchor(var(--diecut-prev) bottom) - 4px);background:linear-gradient(to bottom right,transparent calc(50% - 1px),var(--ink) calc(50% - .5px),var(--ink) calc(50% + .5px),transparent calc(50% + 1px))}R>.pt:first-child:before,R>.pt:first-child:after{content:none}@container(max-width:650px){R>.pt>b{font-size:var(--type-16)}R>.pt>span{font-size:var(--type-14)}R>.pt:nth-child(even)>span{visibility:hidden}}''')
for i in range(1,25):add('chart-line',f'R>.pt:nth-child({i}){{--diecut-self:--diecut-line-{i};--diecut-prev:--diecut-line-{i-1}}}')
