add('radar','''R{position:relative;isolation:isolate;display:flex;align-items:center;justify-content:center;padding:var(--pad)}R:before{content:'';position:absolute;inset:14%;border:var(--stroke) solid var(--n-4);border-radius:50%;background:repeating-radial-gradient(circle,var(--n-1) 0 22%,var(--n-4) 22.2% 22.5%,var(--n-1) 22.7% 44%);z-index:-2}R>.series{position:absolute;inset:18%;background:color-mix(in srgb,var(--a1) 25%,transparent);border:var(--stroke) solid var(--a1);clip-path:polygon(50% calc(50% - var(--v1)/var(--max)*50%),calc(50% + var(--v2)/var(--max)*50%) 35%,calc(50% + var(--v3)/var(--max)*32%) calc(50% + var(--v3)/var(--max)*50%),calc(50% - var(--v4)/var(--max)*32%) calc(50% + var(--v4)/var(--max)*50%),calc(50% - var(--v5)/var(--max)*50%) 35%)}R>.series>.name{position:absolute;bottom:0;font-size:var(--type-14)}R>.axis{position:absolute;left:calc(50% + cos(var(--diecut-angle))*44%);top:calc(50% + sin(var(--diecut-angle))*43%);transform:translate(-50%,-50%);white-space:nowrap}R>.axis .name{font-size:var(--type-18)}''')
