add('bullet','''R.bullets{display:flex;flex-direction:column;gap:var(--gap)}R.bullet{flex:1;display:grid;grid-template-columns:23% 1fr 15%;align-items:center;gap:var(--gap);padding:var(--gap);isolation:isolate}R.bullet>.name{grid-column:1;font-size:var(--type-20)}R.bullet>.fig{grid-column:3;font-size:var(--type-28)}R.bullet>.note{grid-column:2;font-size:var(--type-16)}R.bullet:before{content:'';position:absolute;left:27%;right:17%;top:25%;height:40%;background:linear-gradient(to right,var(--n-2) 0 50%,var(--n-3) 50% 80%,var(--n-4) 80%);z-index:-2}R.bullet:after{content:'';position:absolute;left:27%;top:35%;width:calc(var(--v)*.56%);height:20%;background:var(--a1);z-index:-1}R.bullet>.note:before{content:'';position:absolute;left:calc(27% + var(--target)*.56%);top:20%;height:50%;width:2px;background:var(--ink)}''')
add('slope','''R{display:grid;grid-template-rows:auto repeat(8,minmax(0,1fr));gap:var(--gap-sm);padding:var(--pad);isolation:isolate}R>.heads{display:flex;justify-content:space-between;font-size:var(--type-18);font-weight:var(--label-weight)}R>.pair{position:relative;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:var(--gap);min-height:0}R>.pair>.name{grid-column:2;font-size:var(--type-18);background:var(--page);z-index:2;padding:0 var(--gap-sm)}R>.pair>.a{grid-column:1;grid-row:1;justify-self:start;font-size:var(--type-20);font-weight:var(--figure-weight)}R>.pair>.b{grid-column:3;grid-row:1;justify-self:end;font-size:var(--type-20);font-weight:var(--figure-weight)}R>.pair:before{content:'';position:absolute;left:var(--gap-lg);right:var(--gap-lg);height:var(--stroke);background:var(--n-5);transform:rotate(calc(atan2(var(--a) - var(--b),var(--max))*0.3));z-index:-1}R>.pair.on:before{height:2px;background:var(--a1)}R.dumbbell>.pair:after{content:'';position:absolute;left:calc(var(--a)/var(--max)*65%);width:calc(abs(var(--b) - var(--a))/var(--max)*65%);height:8px;background:var(--a1);border-radius:999px;z-index:-1}''')
add('roadmap','''R{display:flex;flex-direction:column;gap:var(--gap-sm);padding:var(--gap)}R>.heads{display:grid;grid-template-columns:repeat(var(--cols),1fr);margin-left:20%;font-size:var(--type-18);text-align:center}R>.lane{position:relative;flex:1;min-height:0;margin-left:20%;background:repeating-linear-gradient(to right,var(--n-1) 0 calc(100%/var(--cols) - 1px),var(--n-3) calc(100%/var(--cols) - 1px) calc(100%/var(--cols)));border-radius:var(--radius-sm)}R>.lane>.name{position:absolute;right:calc(100% + var(--gap));width:23%;top:40%;font-size:var(--type-18)}R .bar{position:absolute;left:calc(var(--from)/var(--cols)*100%);width:calc((var(--to) - var(--from))/var(--cols)*100%);height:30%;top:20%;display:flex;align-items:center;justify-content:center;padding:var(--gap-sm);background:var(--n-3);border-radius:999px;font-size:var(--type-16)}R .bar.on{background:var(--a1);color:var(--a1-on)}R .bar:nth-of-type(3){top:60%}R .mile{position:absolute;left:calc(var(--at)/var(--cols)*100%);top:60%;width:12px;height:12px;background:var(--ink);transform:rotate(45deg)}R .mile>span{position:absolute;top:var(--gap);white-space:nowrap;transform:rotate(-45deg);font-size:var(--type-14)}''')
