add('mindmap','''R{display:grid;grid-template-columns:1fr 1fr 1fr;grid-template-rows:repeat(3,minmax(0,1fr));gap:var(--gap-lg);padding:var(--pad);isolation:isolate}R>.core{grid-area:2/2;display:flex;align-items:center;justify-content:center;background:var(--a1);color:var(--a1-on);border-radius:999px;text-align:center;padding:var(--gap)}R>.branch{position:relative;display:flex;flex-direction:column;justify-content:center;gap:var(--gap-sm);background:var(--n-1);border:var(--stroke) solid var(--n-4);border-radius:var(--radius-sm);padding:var(--gap)}R>.branch:before{content:'';position:absolute;left:100%;top:50%;height:var(--stroke);width:var(--gap-lg);background:var(--n-5);z-index:-1}R>.branch:nth-child(even){grid-column:1}R>.branch:nth-child(odd){grid-column:3}R>.branch:nth-child(odd):before{left:auto;right:100%}R>.branch.on{background:var(--a1-2-soft)}R .leaf{font-size:var(--type-16);padding-left:var(--gap);border-left:var(--stroke) solid var(--n-5)}R .name{font-size:var(--type-20)}''')
