add('matrix-nine','''R{display:grid;grid-template-columns:var(--gap-lg) repeat(3,minmax(0,1fr));grid-template-rows:repeat(3,minmax(0,1fr)) var(--gap-lg);gap:var(--gap-sm);padding:var(--gap)}R>.axis-x{grid-area:4/2/5/5;display:flex;justify-content:space-around;font-size:var(--type-16)}R>.axis-y{grid-area:1/1/4/2;display:flex;flex-direction:column-reverse;justify-content:space-around;font-size:var(--type-16);writing-mode:vertical-rl;transform:rotate(180deg)}R>.cell{background:var(--n-2);border-radius:var(--radius-sm);padding:var(--gap);display:flex;flex-direction:column;justify-content:center;gap:var(--gap-sm)}R>.cell.on{background:var(--a1);color:var(--a1-on)}R .name{font-size:var(--type-20)}R .note{font-size:var(--type-16)}''')
for i in range(9):add('matrix-nine',f'R>.cell:nth-of-type({i+3}){{grid-column:{i%3+2};grid-row:{i//3+1}}}')
add('positioning','''R{position:relative;margin:var(--gap-lg);border:var(--stroke) solid var(--n-4);border-radius:var(--radius-sm);isolation:isolate}R:before{content:'';position:absolute;left:50%;top:0;bottom:0;width:var(--stroke);background:var(--n-4)}R:after{content:'';position:absolute;top:50%;left:0;right:0;height:var(--stroke);background:var(--n-4)}R>.axis-x{position:absolute;left:var(--gap);right:var(--gap);bottom:var(--gap-sm);display:flex;justify-content:space-between;font-size:var(--type-16)}R>.axis-y{position:absolute;left:var(--gap-sm);top:var(--gap);bottom:var(--gap);display:flex;flex-direction:column-reverse;justify-content:space-between;font-size:var(--type-16)}R>.mark{position:absolute;left:calc(9% + var(--x)*.82%);bottom:calc(12% + var(--y)*.76%);transform:translate(-50%,50%);border-radius:999px;background:var(--n-2);padding:var(--gap-sm) var(--gap);z-index:2;min-width:48px;text-align:center}R>.mark.on{background:var(--a1);color:var(--a1-on)}R>.mark .name{font-size:var(--type-18);white-space:nowrap}R>.mark .seat{width:56px;height:56px}''')
add('network','''R{position:relative;padding:var(--pad);isolation:isolate}R>.node{position:absolute;left:calc(8% + var(--x)*.84%);top:calc(10% + var(--y)*.8%);transform:translate(-50%,-50%);max-width:24%;min-width:60px;background:var(--n-1);border:var(--stroke) solid var(--n-5);border-radius:999px;padding:var(--gap) var(--pad);text-align:center;z-index:2}R>.node.on{background:var(--a1);color:var(--a1-on);border-color:var(--a1)}R>.node .name{font-size:var(--type-20)}R>.link{position:absolute;left:calc(8% + var(--x1)*.84%);top:calc(10% + var(--y1)*.8%);width:calc(hypot((var(--x2) - var(--x1))*.84cqw,(var(--y2) - var(--y1))*.8cqh));height:var(--stroke);background:var(--n-4);transform-origin:left;transform:rotate(atan2((var(--y2) - var(--y1))*.8cqh,(var(--x2) - var(--x1))*.84cqw));z-index:-1}R>.link.strong{height:2px;background:var(--n-7)}@container(max-width:650px){R>.node{padding:var(--gap-sm)}R>.node .name{font-size:var(--type-16)}}''')
add('code','''R{display:flex;flex-direction:column;justify-content:center;gap:var(--gap);background:var(--n-9);color:var(--page);border-radius:var(--radius);padding:var(--pad);counter-reset:line}R>.name{font-size:var(--type-18);border-bottom:var(--stroke) solid var(--n-6);padding-bottom:var(--gap);color:var(--page)}R>.lines{display:flex;flex-direction:column;gap:var(--gap-sm);font-size:var(--type-18);line-height:var(--body-line)}R>.lines>p{white-space:pre-wrap;counter-increment:line;overflow-wrap:anywhere}R.numbered>.lines>p:before{content:counter(line);display:inline-block;min-width:var(--gap-lg);color:var(--n-4)}R .k{color:var(--a1-2)}R .s{color:var(--a2-2)}R .c{color:var(--n-3)}R .n{color:var(--a3-2)}@container(max-width:600px){R>.lines{font-size:var(--type-14)}}''')
# Emit self-contained scopes; aliases R are replaced only on selector positions.
for n,s in css.items():
 s=s.replace('R',root(n))
 # All own implementation variables have explicit page defaults.
 defs={'--diecut-self':'--diecut-null','--diecut-prev':'--diecut-null','--diecut-angle':'0deg','--diecut-area':'var(--a1-2-soft)'}
 j=json.load(open(C/'elements'/n/'element.json'));j['tokenDefaults']={k:v for k,v in defs.items()if k in s};(C/'elements'/n/'element.json').write_text(json.dumps(j,indent=2)+'\n')
 (C/'elements'/n/'element.css').write_text(s)
# Additional contrasting fixtures for categories with only one source fixture.
for n in ['legend','pricing','tag','versus']:
 fs=sorted((C/'elements'/n/'fixtures').glob('*.html'));t=fs[0].read_text()
 t=t.replace('<!-- min:', '<!-- min:',1)
 if n=='legend':t=t.replace('</div>','<span class="key tone-4">지역별 장기 파트너십 운영</span></div>',1)
 elif n=='tag':t=t.replace('신규','우선 검토가 필요한 신규 자동화 과제').replace('핵심','정밀 검사와 생산성 향상')
 elif n=='versus':t=t.replace('기존','현재 공정의 병목 구간과 운영 제약').replace('개선','새로운 자동화 공정 설계')
 else:t=t.replace('스탠더드','글로벌 생산 거점 통합 운영').replace('프로','장기 확장 프로젝트')
 t=re.sub(r'grid-row:\d+ / span \d+','grid-row:1 / span 6',t,count=1)
 (C/'elements'/n/'fixtures/stress-long.html').write_text(t)
print('CSS elements:',len(css))
